NOTES=[
N('Do you know where the station ___?','is','Dolaylı soruda düz cümle sırası kullanılır: where + the station + is. Be fiili öznenin ardından gelir.',{'does':"Dolaylı soruda do/does kullanılmaz; 'the station' + be fiili (is) düz cümle sırasıyla gelir.", 'are':"Özne 'the station' tekil; be fiili is olmalı, are çoğul öznelerle kullanılır."}),
N('Can you tell me what time ___?','the shop opens',"what time'dan sonra özne + fiil gelir: the shop opens. does kullanmak doğrudan soruya özgüdür.",{'does the shop open':'Dolaylı soruda do/does kullanılmaz ve yardımcı fiil özneden önce gelmez.', 'opens the shop':'Özne fiilden önce gelmelidir: the shop opens.'}),
N("I don't know who ___ the window.",'broke','Who sorunun öznesi olduğu için fiil doğrudan arkasından gelir. Geçmiş zaman anlamı için Past Simple: broke.',{'breaking':'Burada çekimli bir fiil gerekir; -ing biçimi cümleyi tamamlayamaz.', 'to broke':"to'dan sonra yalın fiil gelir; 'to broke' ayrıca biçim olarak da hatalıdır."}),
N('Could you tell me where ___?','she lives',"Dolaylı soruda 'where does she live' yerine 'where she lives' denir.",{'does she live':'Dolaylı soruda do/does kullanılmaz; özne + çekimli fiil gelir.', 'lives she':'Özne fiilden önce gelir: she lives.'}),
N('Do you know if he ___ coffee?','likes',"Evet/hayır sorusu if ile başlar, sonra düz cümle gelir. he özneyle Present Simple'da: likes.",{'like':"Üçüncü tekil kişi (he) ile Present Simple'da fiile -s eklenir: likes.", 'liking':'Çekimli bir fiil gerekir; -ing biçimi tek başına cümle kuramaz.'}),
N('I wonder how much this bag ___.','costs',"how much'tan sonra özne + fiil gelir; tekil özne olduğu için costs.",{'cost':"Özne 'this bag' tekil; Present Simple'da fiile -s eklenir: costs.", 'costing':'Çekimli fiil gerekir; costing cümleyi tamamlamaz.'}),
N('Where is the post office? → Do you know ___?','where the post office is',"Doğrudan soru 'Where is the post office?' idi. Dolaylı soruda is özneden sonraya geçer: where the post office is.",{'where is the post office':'Dolaylı soruda yardımcı fiil özneden önce gelmez; sıra düz cümle gibi olmalı.', 'where does the post office is':'Hem does eklenmiş hem de is kullanılmış; dolaylı soruda do/does yoktur.'}),
N('What time does the train leave? → Could you tell me ___?','what time the train leaves','Doğrudan sorudaki does düşer ve fiil özneye uyar: the train leaves.',{'what time does the train leave':'Dolaylı soruda does kullanılmaz; fiil özneye göre çekimlenir.', 'what time the train leave':"Dolaylı soruda does düşer ama fiil yalın kalmaz; tekil özne (the train) ile Present Simple'da -s gerekir: leaves."}),
N('I want to know ___ she is going to the party.','if',"Cümlede 'gidip gitmediği' soruluyor; evet/hayır sorusu dolaylı olduğunda if (ya da whether) kullanılır.",{'that':'that düz bilgi cümlelerinde kullanılır; evet/hayır sorusunu dolaylı hale getirmek için if / whether gerekir.', 'what':'what bir şeyi sorar; burada evet/hayır sorusu var.'}),
N('How old is she? → Do you know how old ___?','she is','Doğrudan soruda is öndeydi; dolaylı soruda özne + be: how old she is.',{'is she':'Dolaylı soruda be fiili özneden sonra gelir.', 'does she':"'how old' sıfat sorusudur, be fiili gerekir; does kullanılmaz."}),
N('Do you know ___ the museum is open?','if','Müzenin açık olup olmadığı soruluyor; dolaylı evet/hayır sorusunda if kullanılır.',{'that':'that evet/hayır sorusunu dolaylı yapmaz; if / whether gerekir.', 'which':"which bir seçenek sorar; burada 'açık mı?' evet/hayır sorusu var."}),
N('Who is that man? → Do you know ___?','who that man is','who bu cümlede özne değil (that man öznedir), bu yüzden sıra düzleşir: who that man is.',{'who is that man':'Dolaylı soruda is özneden sonra gelir.', 'who that man does':'Burada be fiili gerekir; does ana fiil gerektirir.'}),
N('Hangi cümle doğru?','Could you tell me where I can park?',"where'den sonra özne + modal + fiil gelir: where I can park.",{'Could you tell me where can I park?':'Dolaylı soruda modal özneden önce gelmez: where I can park.', 'Could you tell me where do I park?':'Dolaylı soruda do kullanılmaz.'}),
N('Hangi cümle doğru?',"I don't know what she wants.","'what' nesne olduğu için özne + fiil sırası gerekir: what she wants.",{"I don't know what does she want.":'Dolaylı soruda does kullanılmaz.', "I don't know what wants she.":'Özne fiilden önce gelmelidir: what she wants.'}),
N('Hangi cümle doğru?','Do you know whether the museum is open?',"whether'dan sonra düz cümle sırası: the museum is open.",{'Do you know whether is the museum open?':'Dolaylı soruda is özneden önce gelmez.', 'Do you know whether the museum does open?':"Cümlede 'is open' (be + sıfat) var; araya does eklemek hatalıdır ve do/does dolaylı soruda kullanılmaz."}),
N('Hangi cümle "Ne zaman geldi?" sorusunun kibar halidir?','Do you know when he arrived?','Doğrudan soruda did + arrive vardı; dolaylı soruda did düşer ve fiil geçmiş biçimine (arrived) çekilir.',{'Do you know when did he arrive?':'Dolaylı soruda did kullanılmaz; zaman bilgisi fiilin kendisinde (arrived) taşınır.', 'Do you know when he arrive?':'Geçmiş zaman anlamı için fiil Past Simple olmalı: arrived.'}),
N('Hangi cümle doğru?','Do you know who is coming to the party?','who özne olduğu için sıra aynı kalır: who is coming. Dolaylı soruda ek yardımcı fiil gerekmez.',{'Do you know who does come to the party?':"who özne olduğunda does gerekmez; ayrıca 'does come' yanlış vurgu verir.", 'Do you know is who coming to the party?':"Soru kelimesi bildirinin başında olmalıdır; 'is who' sıralaması hatalıdır."}),
N('Hangi cümle YANLIŞ?','Could you tell me where is the library?',"'where is the library' doğrudan soru sırasıdır; Could you tell me ile birlikte kullanıldığında where the library is olmalıdır.",{'Could you tell me where the library is?':'Doğru: dolaylı soruda özne + fiil sırası kullanılmış.', 'Do you know where the library is?':'Doğru: Do you know + where + özne + fiil.'}),
N('Hangi cümle doğru?',"I'd like to know how long the film lasts.","how long'dan sonra özne + fiil gelir: the film lasts.",{"I'd like to know how long does the film last.":'Dolaylı soruda does kullanılmaz.', "I'd like to know how long lasts the film.":'Özne fiilden önce gelmeli: the film lasts.'}),
N('Hangi cümle doğru?','She asked me if I could help her.','Evet/hayır sorusu aktarılırken if eklenir ve düz cümle sırası kullanılır.',{'She asked me could I help her.':'Dolaylı evet/hayır sorusunda if ya da whether gerekir; ayrıca modal özneden önce gelmez.', 'She asked me that I could help her.':'that düz bilgi cümlelerinde kullanılır; soru anlamı için if gerekir.'}),
]
